export const ids=['a','c','r','b','d'];
const parent={a:'r',c:'a',r:null,b:'r',d:'a'},depth={r:0,a:1,b:1,c:2,d:2},height={r:2,a:1,b:0,c:0,d:0};
const colors={r:[160,80,30,255],a:[0,100,255,255],b:[0,200,0,255],c:[230,110,20,255],d:[100,20,180,255]};
const orange=[230,110,20,255],purple=[100,20,180,255],yellow=[255,220,0,255];
export const anchors=['Top','TopRight','Right','BottomRight','Bottom','BottomLeft','Left','TopLeft','Center'];
export function bits(v){const b=new DataView(new ArrayBuffer(8));b.setFloat64(0,v);return b.getBigUint64(0).toString();}
export function authored({phase=0,width=520,height:chartHeight=360,focus=null}={}){
 const order=phase===6?[]:phase===2?[...ids].reverse():ids,index=Object.fromEntries(order.map((id,i)=>[id,i])),values={a:0,c:phase===1?35:30,r:0,b:-0,d:10};
 const raw=order.map(id=>({id,parent:parent[id],label:phase===7&&id==='b'?'':'source-'+id,value:values[id],bits:bits(values[id])})),children=order.map(id=>order.flatMap((child,i)=>parent[child]===id?[i]:[])),bfs=order.length?[index.r]:[];for(let i=0;i<bfs.length;i++)bfs.push(...children[bfs[i]]);
 const norm=phase===2?{r:.4,a:.6,b:.2,c:.8,d:.4}:{r:.6,a:.4,b:.8,c:.2,d:.6};
 const nodes=order.map((id,i)=>({index:i,parent:parent[id]===null?null:index[parent[id]],children:children[i],depth:depth[id],height:height[id],position:[65+depth[id]/2*(width-148),51+norm[id]*(chartHeight-120)],radius:13+3*depth[id],value:values[id],rawBits:bits(values[id]),color:colors[id],markId:'node:'+id}));for(const i of [...bfs].reverse())if(children[i].length)nodes[i].value=children[i].reduce((sum,j)=>sum+nodes[j].value,0);
 const links=bfs.filter(i=>parent[order[i]]!==null).map((target,i)=>{const source=index[parent[order[target]]],a=nodes[source].position,b=nodes[target].position;return{index:i,source,target,sourcePosition:a,targetPosition:b,position:a.map((v,j)=>(v+b[j])/2),markId:phase===5?null:'link:'+order[target],width:phase===3&&order[target]==='c'?0:8,color:phase===4&&order[target]==='c'?[230,110,20,0]:orange};});
 const ancestors=new Set();for(let id=focus;id!==null;id=parent[id]){assert(id in parent);ancestors.add(id);}
 const activity={focus,nodes:order.map(id=>focus===null?null:ancestors.has(id)),links:links.map(l=>focus===null?null:ancestors.has(order[l.target])),flags:[true,false,true,false]};
 return{raw,nodes,links,bfs,index,labels:bfs.map(i=>({position:[...nodes[i].position.slice(0,1),nodes[i].position[1]+4],text:'paint-'+order[i],size:12,rotation:0,anchor:'Middle',color:[45,52,64,255]})),activity,config:[width,chartHeight],margin:[43,29,61,47],plot:[43,29,width-104,chartHeight-76]};
}
export function scenePoint(target,p,t=.42){const e=authored(p),l=e.links.find(l=>e.raw[l.target].id===target);assert(l);return l.sourcePosition.map((v,i)=>v+(l.targetPosition[i]-v)*t);}
export function projected(point,view=[1,0,0]){return point.map((v,i)=>[43,29][i]+(v-[43,29][i])*view[0]+view[i+1]);}
export function resolvedAnchor(requested,client,parentRect,parentCss){if(requested!=='Left'&&requested!=='Right')return requested;const localX=(client[0]-parentRect[0])*parentCss[0]/parentRect[2];return localX<parentRect[2]/2?'Right':'Left';}
export function tooltipBox(requested,client,parentRect,parentCss,size,gap=14){const anchor=resolvedAnchor(requested,client,parentRect,parentCss),axes={Top:[0,-1,-.5,-1],TopRight:[1,-1,0,-1],Right:[1,0,0,-.5],BottomRight:[1,1,0,0],Bottom:[0,1,-.5,0],BottomLeft:[-1,1,-1,0],Left:[-1,0,-1,-.5],TopLeft:[-1,-1,-1,-1],Center:[0,0,-.5,-.5]}[anchor],local=client.map((v,i)=>(v-parentRect[i])*parentCss[i]/parentRect[i+2]);return{anchor,rect:[parentRect[0]+(Math.round(local[0]+axes[0]*gap)+axes[2]*size[0])*parentRect[2]/parentCss[0],parentRect[1]+(Math.round(local[1]+axes[1]*gap)+axes[3]*size[1])*parentRect[3]/parentCss[1],size[0]*parentRect[2]/parentCss[0],size[1]*parentRect[3]/parentCss[1]]};}
// Compare the exact complete bitmap without handing a large unequal Buffer
// to AssertionError's object/string diff formatter. Diagnostics stay bounded.
function exactPixels(actual,wanted,width,label){const a=Buffer.from(actual.buffer,actual.byteOffset,actual.byteLength),b=Buffer.from(wanted.buffer,wanted.byteOffset,wanted.byteLength);if(a.equals(b))return{exact:true,checkedBytes:a.length,checkedPixels:a.length/4};let changedPixels=0,changedChannels=0,maxDelta=0,minX=Infinity,minY=Infinity,maxX=-1,maxY=-1;const first=[];for(let offset=0;offset<Math.min(a.length,b.length);offset+=4){let differs=false;for(let c=0;c<4&&offset+c<Math.min(a.length,b.length);c++)if(a[offset+c]!==b[offset+c]){changedChannels++;differs=true;maxDelta=Math.max(maxDelta,Math.abs(a[offset+c]-b[offset+c]));}if(differs){changedPixels++;const pixel=offset/4,x=pixel%width,y=Math.floor(pixel/width);minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);if(first.length<16)first.push({pixel:[x,y],actual:[...a.subarray(offset,offset+4)],wanted:[...b.subarray(offset,offset+4)]});}}const diagnostic={label,tolerance:0,width,actualBytes:a.length,wantedBytes:b.length,lengthMismatch:a.length!==b.length,changedPixels,changedChannels,maxDelta,bbox:changedPixels?[minX,minY,maxX,maxY]:null,first,sampleLimit:16,actualDecodedSHA256:sha(a),wantedDecodedSHA256:sha(b)};const error=new Error('exact whole-image comparison failed: '+JSON.stringify(diagnostic));error.name='ExactPixelMismatch';error.pixelComparison=diagnostic;throw error;}
