export function validateFrame(frame,p){const e=authored(p);assert.deepEqual(frame.config,e.config);assert.deepEqual(frame.margin,e.margin);coordinates(frame.plot,e.plot);assert.deepEqual(frame.raw,e.raw);for(const d of frame.raw)assert.equal(bits(d.value),d.bits);assert(frame.pool);assert.equal(frame.nodes.length,e.nodes.length);for(let i=0;i<e.nodes.length;i++){coordinates(frame.nodes[i].position,e.nodes[i].position);assert.deepEqual({...frame.nodes[i],position:null},{...e.nodes[i],position:null});}assert.equal(frame.links.length,e.links.length);for(let i=0;i<e.links.length;i++){const actual=frame.links[i],wanted=e.links[i];for(const key of['position','sourcePosition','targetPosition'])coordinates(actual[key],wanted[key]);assert.deepEqual({...actual,position:null,sourcePosition:null,targetPosition:null},{...wanted,position:null,sourcePosition:null,targetPosition:null});}assert.equal(frame.labels.length,e.labels.length);frame.labels.forEach((l,i)=>{coordinates(l.position,e.labels[i].position);assert.deepEqual({...l,position:null},{...e.labels[i],position:null});});assert.deepEqual(frame.activity,e.activity);assert.deepEqual(frame.theme,{background:[255,255,255,255],text:[45,52,64,255],colors:[purple,[0,180,200,255],yellow],fontSize:12,font:'FontOptions { family: None, weight: None }'});assert.deepEqual(frame.marks.map(m=>m.id),[...e.links.flatMap(l=>l.markId?[l.markId]:[]),...e.bfs.map(i=>'node:'+e.raw[i].id)]);for(const mark of frame.marks){assert.equal(mark.opacity,1);if(mark.id.startsWith('node:')){const id=mark.id.slice(5),i=e.index[id];assert.equal(mark.series,id);assert.equal(mark.label,e.raw[i].label);assert.equal(mark.value,e.nodes[i].value);assert.equal(mark.bits,bits(e.nodes[i].value));assert.deepEqual(mark.fill,colors[id]);assert.equal(mark.stroke,null);coordinates(mark.geometry.match(/[-+]?(?:\d*\.)?\d+(?:e[-+]?\d+)?/gi).map(Number),[...e.nodes[i].position,e.nodes[i].radius]);}else{const l=e.links.find(l=>l.markId===mark.id);assert.equal(mark.series,'');assert.equal(mark.label,'');assert.equal(mark.value,0);assert.equal(mark.fill,null);assert.deepEqual(mark.stroke,l.width>0?{width:l.width,color:l.color,cap:'Round'}:null);coordinates(mark.geometry.match(/[-+]?(?:\d*\.)?\d+(?:e[-+]?\d+)?/gi).map(Number),[...l.sourcePosition,...l.targetPosition]);}}return e;}
function layerSpecs(mode=0){const rows=[['links','link'],['nodes','node'],['labels','label']];if(mode===1)rows.splice(2,0,['links-again','link']);if(mode===2)rows.shift();if(mode===3||mode===6)rows.push(['mesh','mesh']);if(mode===4||mode===5||mode===6)rows.push(['panel','custom']);if(mode===5)rows.unshift(['mesh','mesh']);return rows.map(([key,role],index)=>({key,role,index}));}
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
if(process.argv.includes('--oracle-only')){const e=authored();assert.deepEqual(e.bfs.map(i=>e.raw[i].id),['r','a','b','c','d']);coordinates(e.nodes[e.index.r].position,[65,195]);coordinates(scenePoint('c',{}),[329.12,126.84]);assert.equal(e.raw[e.index.b].bits,'9223372036854775808');assert.equal(e.nodes[e.index.a].value,40);assert.equal(authored({phase:1}).nodes[0].value,45);assert.equal(resolvedAnchor('Left',[300,100],[0,0,650,288],[520,360]),'Right','requested left/right compares xLocal with physical BCR half');assert.equal(resolvedAnchor('Left',[300,100],[0,0,520,360],[520,360]),'Left');console.log('Independent link-tooltip author model passed; no browser/runtime claim.');}
