 document.querySelector('.panels').style.display='none';document.querySelector('nav').style.display='none';window.tltNative=[];window.tltKey=null;window.tltIds=new WeakMap();window.tltNextId=1;window.tltEvents=new WeakMap();window.tltNextEvent=1;
