 const rect=n=>{const r=n.getBoundingClientRect();return[r.x,r.y,r.width,r.height];},metrics=n=>{const c=getComputedStyle(n);return{rect:rect(n),css:[Number.parseFloat(c.width),Number.parseFloat(c.height)],rawCss:[c.width,c.height]};};
