  const sequence=window.tltNextEvent++;window.tltEvents.set(event,sequence);const target=event.target instanceof Element?event.target:null,related=event.relatedTarget instanceof Element?event.relatedTarget:null,key=window.tltKey,root=key?document.getElementById('tree-link-tooltip-'+key):null,surface=root?.querySelector('.kartis-surface');
