  const read=n=>n?{identity:window.tltId(n),tag:n.tagName,namespace:n.namespaceURI,mark:n.closest('[data-id]')?.getAttribute('data-id')??null,markOpacity:n.closest('[data-id]')?.getAttribute('opacity')??null,key:n.closest('[data-tree-svg-key]')?.getAttribute('data-tree-svg-key')??null,mesh:n.closest('[data-tree-svg-mesh]')!==null,root:n.closest('[id^="tree-link-tooltip-"]')?.id??null,browser:window.tltId(n.closest('.kartis-browser')),connected:n.isConnected,inert:n.closest('[inert]')!==null}:null;
